            for (int i1 = 0; i1 <= n - len; ++i1) {
                // 枚举s2的起始位置
                for (int i2 = 0; i2 <= n - len; ++i2) {
                    // 枚举分割的位置
                    for (int i = 1; i < len; ++i) {
                        if (dp[i1][i2][i] && dp[i1 + i][i2 + i][len - i]) {
                            dp[i1][i2][len] = true;
